package __PKG__;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import org.bukkit.Bukkit;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.command.PluginCommand;
import org.bukkit.command.TabExecutor;
import org.bukkit.entity.Player;

/**
 * The custom items of the resource pack and the command that hands them out:
 * /__CMD__ <item> [amount] [player]. Generated by Minecraft Builder.
 */
public final class CustomItems implements TabExecutor {
    /** key, base item, model, name, lore */
    static final String[][] ITEMS = {
__ITEMS__
    };

    private CustomItems() {}

    static void init(__MAIN__ plugin) {
        PluginCommand c = plugin.getCommand("__CMD__");
        if (c == null) return;
        CustomItems x = new CustomItems();
        c.setExecutor(x);
        c.setTabCompleter(x);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 0) {
            StringBuilder sb = new StringBuilder("&7Items: &f");
            for (int i = 0; i < ITEMS.length; i++) sb.append(i > 0 ? "&7, &f" : "").append(ITEMS[i][0]);
            sender.sendMessage(Util.color(sb.toString()));
            return true;
        }
        String[] item = null;
        for (String[] it : ITEMS) {
            if (it[0].equalsIgnoreCase(args[0])) item = it;
        }
        if (item == null) {
            sender.sendMessage(Util.color("&cUnknown item: " + args[0]));
            return true;
        }
        double amount = args.length > 1 ? Math.max(1, Util.num(args[1])) : 1;
        Player target = args.length > 2 ? Bukkit.getPlayerExact(args[2]) : (sender instanceof Player p ? p : null);
        if (target == null) {
            sender.sendMessage(Util.color("&cPlayer not found."));
            return true;
        }
        Util.giveCustom(target, item[1], amount, item[2], item[3], item[4]);
        sender.sendMessage(Util.color("&a" + target.getName() + " &7+ &f" + (int) amount + "x " + item[0]));
        return true;
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String alias, String[] args) {
        List<String> out = new ArrayList<>();
        String cur = args.length == 0 ? "" : args[args.length - 1].toLowerCase(Locale.ROOT);
        if (args.length <= 1) {
            for (String[] it : ITEMS) {
                if (it[0].startsWith(cur)) out.add(it[0]);
            }
        } else if (args.length == 2) {
            for (String n : new String[] { "1", "16", "64" }) {
                if (n.startsWith(cur)) out.add(n);
            }
        } else if (args.length == 3) {
            for (Player p : Bukkit.getOnlinePlayers()) {
                if (p.getName().toLowerCase(Locale.ROOT).startsWith(cur)) out.add(p.getName());
            }
        }
        return out;
    }
}
